window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-769d10c36801de19"]={"versions": [{"id": "FIG-769d10c36801de19", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des AUTOSAR E2E-Protokolls (Profile 4m). Das Diagramm stellt den finalen Teilschritt „Write CRC“ innerhalb der Funktionen <code>E2E_P04mProtect()</code> und <code>E2E_P04mForward()</code> auf Ebene der Software-Bibliothek AUTOSAR E2E dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm referenziert über zwei abgerundete Kontextmarken oben links die ausführenden Funktionen <code>E2E_P04mProtect()</code> und <code>E2E_P04mForward()</code>. Die Entitäten und Datenstrukturen umfassen:</p>\n<ul class=\"fig-list\"><li>Lokale Variable <code>CRC</code>: 4-Byte-Prüfsummenwert (32-Bit CRC).\n</li><li>Nutzdaten-Puffer <code>Data[]</code>: Byte-Array zur Aufnahme des serialisierten E2E-Datenstroms.\n</li><li><code>Offset</code>: Konfigurationsparameter (Bit-/Byte-Offset der E2E-Headerstruktur im Datenfeld).\n</li><li>Zielbereich <code>Data[Offset+8...Offset+11]</code>: Vier aufeinanderfolgende Bytes im Puffer für die Speicherung des Prüfsummenwerts.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf ist sequenziell und linear:</p>\n<ol class=\"fig-list\"><li>Start am Initialknoten (ausgefüllter Kreis).\n</li><li>Übergang zur Aktionsaktivität „Copy 4-byte local variable CRC on bytes Data[Offset+8...Offset+11] using big Endian order“: Die 4 Byte der zuvor berechneten lokalen Variablen <code>CRC</code> werden in Big-Endian-Bytereihenfolge in das Byte-Array <code>Data</code> an die Indizes <code>Offset + 8</code> bis <code>Offset + 11</code> geschrieben.\n</li><li>Übergang zum Endknoten (Aktivitätsendknoten, Bullseye-Symbol).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Anforderung <code>[PRS_E2E_00766]</code> für AUTOSAR Classic und Adaptive Platform. Bei der Implementierung ist zwingend darauf zu achten, dass die 32-Bit-Variable <code>CRC</code> unabhängig von der nativen Host-Endianness des Microcontrollers stets in Big-Endian-Reihenfolge (Most Significant Byte an <code>Data[Offset+8]</code>, Least Significant Byte an <code>Data[Offset+11]</code>) in das Datenarray serialisiert wird. Der Puffer muss an der Position <code>Offset+11</code> allokiert und schreibbar sein.</p>"}, {"id": "FIG-c363ba182da34f8f", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des internen Kontrollflusses des AUTOSAR E2E-Protokolls (Profile 4m). Das Diagramm stellt den finalen Teilschritt „Write CRC“ innerhalb der Funktionen <code>E2E_P04mProtect()</code> und <code>E2E_P04mForward()</code> auf Ebene der Software-Bibliothek AUTOSAR E2E dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm referenziert über zwei abgerundete Kontextmarken oben links die ausführenden Funktionen <code>E2E_P04mProtect()</code> und <code>E2E_P04mForward()</code>. Die Entitäten und Datenstrukturen umfassen:</p>\n<ul class=\"fig-list\"><li>Lokale Variable <code>CRC</code>: 4-Byte-Prüfsummenwert (32-Bit CRC).\n</li><li>Nutzdaten-Puffer <code>Data[]</code>: Byte-Array zur Aufnahme des serialisierten E2E-Datenstroms.\n</li><li><code>Offset</code>: Konfigurationsparameter (Bit-/Byte-Offset der E2E-Headerstruktur im Datenfeld).\n</li><li>Zielbereich <code>Data[Offset+8...Offset+11]</code>: Vier aufeinanderfolgende Bytes im Puffer für die Speicherung des Prüfsummenwerts.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf ist sequenziell und linear:</p>\n<ol class=\"fig-list\"><li>Start am Initialknoten (ausgefüllter Kreis).\n</li><li>Übergang zur Aktionsaktivität „Copy 4-byte local variable CRC on bytes Data[Offset+8...Offset+11] using big Endian order“: Die 4 Byte der zuvor berechneten lokalen Variablen <code>CRC</code> werden in Big-Endian-Bytereihenfolge in das Byte-Array <code>Data</code> an die Indizes <code>Offset + 8</code> bis <code>Offset + 11</code> geschrieben.\n</li><li>Übergang zum Endknoten (Aktivitätsendknoten, Bullseye-Symbol).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend gemäß Anforderung <code>[PRS_E2E_00766]</code> für AUTOSAR Classic und Adaptive Platform. Bei der Implementierung ist zwingend darauf zu achten, dass die 32-Bit-Variable <code>CRC</code> unabhängig von der nativen Host-Endianness des Microcontrollers stets in Big-Endian-Reihenfolge (Most Significant Byte an <code>Data[Offset+8]</code>, Least Significant Byte an <code>Data[Offset+11]</code>) in das Datenarray serialisiert wird. Der Puffer muss an der Position <code>Offset+11</code> allokiert und schreibbar sein.</p>"}], "trans": [{"from": "FIG-769d10c36801de19", "to": "FIG-c363ba182da34f8f", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
